# generated by aitest
import decimal
import tomli


def test_decimal_float():
    data = tomli.loads("f = 3.14\ng = 1e3\n", parse_float=decimal.Decimal)
    assert isinstance(data["f"], decimal.Decimal)
    assert data["f"] == decimal.Decimal("3.14")
    assert isinstance(data["g"], decimal.Decimal)
    assert data["g"] == decimal.Decimal("1e3")
